def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    ox, oy = observation['opponent_position']
    obstacles = set(map(tuple, observation['obstacles']))
    resources = observation['resources']
    score_self, score_opp = observation['scores']

    def safe_move(dx, dy):
        nx, ny = px + dx, py + dy
        if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
            return True
        return False

    # Prioritize moving towards resources if available
    if resources:
        rst = sorted(resources, key=lambda r: abs(r['x'] - px) + abs(r['y'] - py))
        tx, ty = rst[0]['x'], rst[0]['y']
        dx = 0 if tx == px else (1 if tx > px else -1)
        dy = 0 if ty == py else (1 if ty > py else -1)
        if safe_move(dx, dy):
            return [dx, dy]
        # Try alternate directions if blocked
        for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
            if safe_move(dx, dy):
                return [dx, dy]
    else:
        # No resources: chase opponent if behind
        dx, dy = (0,0)
        if score_self <= score_opp:
            dx = 1 if ox > px else -1 if ox < px else 0
            dy = 1 if oy > py else -1 if oy < py else 0
            if safe_move(dx, dy):
                return [dx, dy]
        # Else stay still or move randomly
        for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
            if safe_move(dx, dy):
                return [dx, dy]
    # Default to staying still
    return [0, 0]
